import{_ as t,o as e,c as o,a2 as s}from"./chunks/framework.CQdiwDJy.js";const u=JSON.parse('{"title":"单轮问答（tau ask）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ask.md","filePath":"guide/ask.md","lastUpdated":1788601681000}'),d={name:"guide/ask.md"};function i(r,a,n,h,l,c){return e(),o("div",null,[...a[0]||(a[0]=[s(`<h1 id="单轮问答-tau-ask" tabindex="-1">单轮问答（tau ask） <a class="header-anchor" href="#单轮问答-tau-ask" aria-label="Permalink to &quot;单轮问答（tau ask）&quot;">​</a></h1><p><code>tau ask</code> 是 Tau 的历史正门：一个意图进，一份计划、一次执行、一个结果出。适合&quot;查一下&quot;、&quot;找出来&quot;、&quot;帮我读这个文件&quot;这类可以一步完成或按固定步骤完成的任务。</p><h2 id="基本用法" tabindex="-1">基本用法 <a class="header-anchor" href="#基本用法" aria-label="Permalink to &quot;基本用法&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tau</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;找出超过 1MB 的日志文件&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tau</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;读一下 package.json 并总结依赖&quot;</span></span></code></pre></div><p>执行过程会展示：AI 的规划说明、每一个步骤（工具或 shell 命令）、安全审查结论，然后请求你的确认（低风险只读计划可用 <code>--yes</code> 跳过交互）。</p><h2 id="流式思考-v0-5-0" tabindex="-1">流式思考（v0.5.0） <a class="header-anchor" href="#流式思考-v0-5-0" aria-label="Permalink to &quot;流式思考（v0.5.0）&quot;">​</a></h2><p>v0.5.0 起，规划轮可以流式透出 provider 的思考过程（reasoning delta）：DeepSeek 的 <code>reasoning_content</code>、Anthropic 的 <code>thinking_delta</code>、Gemini 的 thought parts 都以独立通道到达，与计划正文分开；组装出的计划仍要经过与缓冲模式完全一致的严格 JSON 校验与确定性审查——流式只改变&quot;何时看到&quot;，不改变&quot;能否执行&quot;。</p><p>这一能力目前在 <strong>WebUI</strong> 中呈现：规划进行时思考实时流入计划卡顶部的可折叠面板。CLI 尚未暴露 <code>--stream</code> 旗标——库层 API（<code>planIntentStream</code> / <code>onPlanStream</code>）已就绪，可供自建集成直接使用。</p><h2 id="上下文与附件-v0-6-0-库层" tabindex="-1">上下文与附件（v0.6.0 库层） <a class="header-anchor" href="#上下文与附件-v0-6-0-库层" aria-label="Permalink to &quot;上下文与附件（v0.6.0 库层）&quot;">​</a></h2><p>v0.6.0 起，规划管线原生携带两类上下文：<strong>会话历史</strong>（<code>priorTurns</code>，折叠进规划意图）与<strong>图片附件</strong>（<code>attachments</code>，视觉 provider 收到原生格式、纯文本 provider 得到诚实注记）。<code>tau ask</code> 仍是单轮纯文本——这两类上下文目前由 WebUI 的对话线程与图片附件呈现；库层使用者可直接通过 <code>planIntent()</code> 的 options（<code>priorTurns</code> / <code>attachments</code>）接入。</p><h2 id="与-tau-goal-的区别" tabindex="-1">与 tau goal 的区别 <a class="header-anchor" href="#与-tau-goal-的区别" aria-label="Permalink to &quot;与 tau goal 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>tau ask</th><th>tau goal</th></tr></thead><tbody><tr><td>轮次</td><td>1</td><td>最多 5（默认 3）</td></tr><tr><td>反思</td><td>无</td><td>每轮后 provider 决定是否继续</td></tr><tr><td>适用</td><td>明确的单步任务</td><td>需要根据执行结果调整的任务</td></tr></tbody></table><p><code>tau ask</code> 执行完毕就结束；如果 provider 认为还需要一轮，那不是 ask 的事——请改用 <a href="/Tau/guide/goal.html">tau goal</a>。</p><h2 id="退出码与管道" tabindex="-1">退出码与管道 <a class="header-anchor" href="#退出码与管道" aria-label="Permalink to &quot;退出码与管道&quot;">​</a></h2><p><code>tau ask</code> 遵循 Unix 约定：成功返回 0，失败返回非 0，结果文本走 stdout、日志走 stderr，可以直接接入管道与 CI 脚本。</p>`,15)])])}const k=t(d,[["render",i]]);export{u as __pageData,k as default};
